                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_7" value="H"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_1" id="ielts_listening_answer_12226_1_8" value="I"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-15" class="ielts-q-badge">15</strong> <span>Pedestrian crossing</span></td>
                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12226_2" id="ielts_listening_answer_12226_2_6" value="G"></td>                                                                                                            <td class="ielts