INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(13013, 1301, 'listening', 'Listening Part 3', '<div class="ielts-reading-container">
<h2 class="ielts-reading-question-section-heading">
                                            Questions 21-25                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="21"><div class="ielts-q-header"><strong class="ielts-q-badge">21</strong><span class="ielts-q-title"><span>Why is Jack interested in investigating seed germination?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="A"><span class="ielts-radio-text"><strong>A</strong> He may do a module on a related topic later on.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="B"><span class="ielts-radio-text"><strong>B</strong> He wants to have a career in plant science.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="C"><span class="ielts-radio-text"><strong>C</strong> He is thinking of choosing this topic for his dissertation.</span></label></div></div><div class="ielts-standalone-q" data-qnum="22"><div class="ielts-q-header"><strong class="ielts-q-badge">22</strong><span class="ielts-q-title"><span>Jack and Emma agree the main advantage of their present experiment is that it can be</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="A"><span class="ielts-radio-text"><strong>A</strong> described very easily.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="B"><span class="ielts-radio-text"><strong>B</strong> carried out inside the laboratory.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="C"><span class="ielts-radio-text"><strong>C</strong> completed in the time available.</span></label></div></div><div class="ielts-standalone-q" data-qnum="23"><div class="ielts-q-header"><strong class="ielts-q-badge">23</strong><span class="ielts-q-title"><span>What do they decide to check with their tutor?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="A"><span class="ielts-radio-text"><strong>A</strong> whether their aim is appropriate</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="B"><span class="ielts-radio-text"><strong>B</strong> whether anyone else has chosen this topic</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="C"><span class="ielts-radio-text"><strong>C</strong> whether the assignment contributes to their final grade</span></label></div></div><div class="ielts-standalone-q" data-qnum="24"><div class="ielts-q-header"><strong class="ielts-q-badge">24</strong><span class="ielts-q-title"><span>They agree that Graves’ book on seed germination is disappointing because</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="A"><span class="ielts-radio-text"><strong>A</strong> it fails to cover recent advances in seed science.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="B"><span class="ielts-radio-text"><strong>B</strong> the content is irrelevant for them.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="C"><span class="ielts-radio-text"><strong>C</strong> its focus is very theoretical.</span></label></div></div><div class="ielts-standalone-q" data-qnum="25"><div class="ielts-q-header"><strong class="ielts-q-badge">25</strong><span class="ielts-q-title"><span>What does Jack say about the article on seed germination by Lee Hall?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="25" name="question_25" value="A"><span class="ielts-radio-text"><strong>A</strong> The diagrams of plant development are useful.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="25" name="question_25" value="B"><span class="ielts-radio-text"><strong>B</strong> The analysis of seed germination statistics is thorough.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="25" name="question_25" value="C"><span class="ielts-radio-text"><strong>C</strong> The findings on seed germination after fires are surprising.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 26-30                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <div class="ielts-listening-section-content-wrapper"><p>Complete the flow-chart below.</p>
<p><em>Choose <strong>FIVE</strong> answers from the box and write the correct letter, <strong>A-H</strong>, next to Questions</em></p>
<p style="text-align: center"> <strong>Stage in the experiment</strong></p>
<p style="text-align: center">Select seeds of different <span class="ielts-listening-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">26</strong><select data-qnum="26" name="question_26" class="ielts-inline-select"><option value="">[ 26 ] Tanlang...</option><option value="A. container">A. container</option><option value="B. soil">B. soil</option><option value="C. weight">C. weight</option><option value="D. condition">D. condition</option><option value="E. height">E. height</option><option value="F. colour">F. colour</option><option value="G. types">G. types</option><option value="H. depths">H. depths</option></select></span></span> and sizes.</p>
<p style="text-align: center">↓</p>
<p style="text-align: center">Measure and record the <span class="ielts-listening-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">27</strong><select data-qnum="27" name="question_27" class="ielts-inline-select"><option value="">[ 27 ] Tanlang...</option><option value="A. container">A. container</option><option value="B. soil">B. soil</option><option value="C. weight">C. weight</option><option value="D. condition">D. condition</option><option value="E. height">E. height</option><option value="F. colour">F. colour</option><option value="G. types">G. types</option><option value="H. depths">H. depths</option></select></span></span> and size of each one.</p>
<p style="text-align: center">↓</p>
<p style="text-align: center">Decide on the <span class="ielts-listening-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">28</strong><select data-qnum="28" name="question_28" class="ielts-inline-select"><option value="">[ 28 ] Tanlang...</option><option value="A. container">A. container</option><option value="B. soil">B. soil</option><option value="C. weight">C. weight</option><option value="D. condition">D. condition</option><option value="E. height">E. height</option><option value="F. colour">F. colour</option><option value="G. types">G. types</option><option value="H. depths">H. depths</option></select></span></span> to be used.</p>
<p style="text-align: center">↓</p>
<p style="text-align: center">Use a different <span class="ielts-listening-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">29</strong><select data-qnum="29" name="question_29" class="ielts-inline-select"><option value="">[ 29 ] Tanlang...</option><option value="A. container">A. container</option><option value="B. soil">B. soil</option><option value="C. weight">C. weight</option><option value="D. condition">D. condition</option><option value="E. height">E. height</option><option value="F. colour">F. colour</option><option value="G. types">G. types</option><option value="H. depths">H. depths</option></select></span></span> for each seed and label it.</p>
<p style="text-align: center">↓</p>
<p style="text-align: center">After about 3 weeks, record the plant’s <span class="ielts-listening-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">30</strong><select data-qnum="30" name="question_30" class="ielts-inline-select"><option value="">[ 30 ] Tanlang...</option><option value="A. container">A. container</option><option value="B. soil">B. soil</option><option value="C. weight">C. weight</option><option value="D. condition">D. condition</option><option value="E. height">E. height</option><option value="F. colour">F. colour</option><option value="G. types">G. types</option><option value="H. depths">H. depths</option></select></span></span>.</p>
<p style="text-align: center">↓</p>
<p style="text-align: center">Investigate the findings.</p>
</div>                                                <div class="options-dnd-panel dnd-panel dnd-panel--inline" data-dnd-group="12232">
                                                    <div class="dnd-panel-instruction">Drag and drop an option to fill in each blank.</div>
                                                    <div class="dnd-cards-container">
                                                                                                                    <div class="dnd-card" draggable="true" data-value="A" data-text="A. container">
                                                                <span class="dnd-label">A.</span>
                                                                <span class="dnd-text">container</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="B" data-text="B. soil">
                                                                <span class="dnd-label">B.</span>
                                                                <span class="dnd-text">soil</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="C" data-text="C. weight">
                                                                <span class="dnd-label">C.</span>
                                                                <span class="dnd-text">weight</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="D" data-text="D. condition">
                                                                <span class="dnd-label">D.</span>
                                                                <span class="dnd-text">condition</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="E" data-text="E. height">
                                                                <span class="dnd-label">E.</span>
                                                                <span class="dnd-text">height</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="F" data-text="F. colour">
                                                                <span class="dnd-label">F.</span>
                                                                <span class="dnd-text">colour</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="G" data-text="G. types">
                                                                <span class="dnd-label">G.</span>
                                                                <span class="dnd-text">types</span>
                                                            </div>
                                                                                                                    <div class="dnd-card" draggable="true" data-value="H" data-text="H. depths">
                                                                <span class="dnd-label">H.</span>
                                                                <span class="dnd-text">depths</span>
                                                            </div>
                                                                                                            </div>
                                                </div>
